//@ts-check
/**
 * The Binance live-market boundary: real streaming market data through
 * OUR strict-JSON streaming reader, end to end. Every WebSocket message
 * and the REST seed response are parsed by `createJsonxStreamReader`
 * (`mode: 'json'`) — the built-in JSON parser appears nowhere in this
 * file (a test greps for it) — and accumulate through
 * `createStreamAdapter`'s document-boundary mode into a live price line
 * and a 1m-kline candlestick chart.
 *
 * Verified endpoints (binance-spot-api-docs, checked 2026-07-21):
 *  - WebSocket (market data only): wss://data-stream.binance.vision
 *    combined streams: /stream?streams=<a>/<b> wrapping payloads as
 *    {"stream": name, "data": payload}
 *    sample miniTicker payload: {"e":"24hrMiniTicker","E":1721556000000,
 *      "s":"BTCUSDT","c":"64123.45","o":"63321.00","h":"64800.10",
 *      "l":"62950.00","v":"18234.51","q":"1167034521.11"}
 *    sample kline payload: {"e":"kline","E":1721556001000,"s":"BTCUSDT",
 *      "k":{"t":1721555940000,"T":1721555999999,"o":"64100.0",
 *           "h":"64150.2","l":"64080.1","c":"64123.4","v":"12.5",
 *           "n":480,"x":false, …}}
 *  - REST seed (no API key): https://data-api.binance.vision
 *    GET /api/v3/klines?symbol=BTCUSDT&interval=1m&limit=60
 *    each row: [openTime, "open", "high", "low", "close", "volume",
 *               closeTime, "quoteVolume", trades, …]
 *
 * Ground rules: the connection is opt-in per user gesture (the
 * "Go live" button dispatches `binance/toggle`; nothing connects on
 * page load), one automatic reconnect on a transient close (then stop
 * and say so), rAF-batched re-renders (never per message), ring-buffer
 * bounded memory, and every failure renders a readable status — the
 * page never depends on the feed.
 */

import { createJsonxStreamReader } from '@jarenjs/josl';
import { compileChart, createChartSession } from '@jarenjs/charts';
import { createStreamAdapter } from '@jarenjs/charts/stream-adapter';

import { cards, error, callout, chart, more } from '../lib/nodes.js';
import { siteText } from '../messages.js';

/** The site's words in English: what a caller that passes none reads. */
const ENGLISH = siteText();
/** The words getter of a caller that passes none. */
const englishWords = () => ENGLISH;

const WS_BASE = 'wss://data-stream.binance.vision';
const REST_BASE = 'https://data-api.binance.vision';
const SYMBOLS = ['BTCUSDT', 'ETHUSDT'];
const KLINE_SYMBOL = 'BTCUSDT';
const STREAMS = [
  ...SYMBOLS.map((s) => `${s.toLowerCase()}@miniTicker`),
  `${KLINE_SYMBOL.toLowerCase()}@kline_1m`,
];

/** The live price chart definition. The two symbols trade at price
 * levels far apart, so each reads its own value axis: on one shared
 * scale the higher one draws as a flat line along the top and the lower
 * one as a flat line along the bottom. */
const priceConfig = (say) => ({
  type: 'line',
  title: say('site/charts/live/price-title'),
  x: 'time',
  yLabel: `${SYMBOLS[0]} (USDT)`,
  y2: { series: [SYMBOLS[1]], label: `${SYMBOLS[1]} (USDT)` },
});

/** The kline chart definition. The step-quantized y domain keeps the
 * scales still while the open candle's prices wiggle inside it, so the
 * incremental session patches one candle group per update instead of
 * recompiling the chart. */
const klineConfig = (say) => ({
  type: 'candlestick',
  title: say('site/charts/live/kline-title', { symbol: KLINE_SYMBOL }),
  yLabel: 'USDT',
  domain: { y: 'step' },
});

/**
 * The socket-free feed core: message text in, chart data out. Testable
 * offline with vendored payloads.
 * @param {(id: any, params?: Record<string, unknown>) => string} [say] - the
 *   site's words for the candlestick's title (English by default)
 */
export function createBinanceFeed(say = ENGLISH) {
  // combined-stream envelopes nest the payload under `data`; kline
  // fields nest one deeper under `data.k`
  const price = createStreamAdapter('line', {
    recordBoundary: 'document',
    recordPath: ['data'],
    xField: 'E',
    yField: 'c',
    seriesField: 's',
    maxPoints: 240,
  });
  const klines = createStreamAdapter('candlestick', {
    recordBoundary: 'document',
    recordPath: ['data', 'k'],
    xField: 't',
    openField: 'o',
    highField: 'h',
    lowField: 'l',
    closeField: 'c',
    maxPoints: 60,
    changes: true,
  });
  const klineSession = createChartSession(klineConfig(say), klines, { theme: 'host' });
  const klineModes = { unchanged: 0, incremental: 0, rebuilt: 0 };
  let messages = 0;
  let drops = 0;

  const sink = (event) => {
    price.onEvent(event);
    klines.onEvent(event);
  };

  /** One message through the strict reader into both adapters; whether it parsed. */
  function ingest(text) {
    try {
      const reader = createJsonxStreamReader({ mode: 'json', onEvent: sink });
      reader.feed(String(text));
      reader.end();
      price.endDocument();
      klines.endDocument();
      return true;
    }
    catch {
      price.abortDocument();
      klines.abortDocument();
      return false;
    }
  }

  return {
    /** One complete WebSocket message. */
    handleMessage(text) {
      messages++;
      if (!ingest(text)) drops++;
    },

    /**
     * Seed the candlestick from a REST klines response BODY (text!).
     * Each row becomes a synthetic kline message through the exact
     * message path — no special cases — but is not a feed message: the
     * `messages` and `drops` counts are the WebSocket's, so a seed row
     * that fails to parse is skipped like a malformed row.
     * @param {string} bodyText
     */
    seedKlines(bodyText) {
      const reader = createJsonxStreamReader({ mode: 'json' });
      reader.feed(String(bodyText));
      const rows = reader.end();
      if (!Array.isArray(rows)) return;
      for (const row of rows) {
        if (!Array.isArray(row) || row.length < 5) continue;
        ingest(`{"stream":"seed","data":{"k":{"t":${Number(row[0])},"o":"${row[1]}","h":"${row[2]}","l":"${row[3]}","c":"${row[4]}"}}}`);
      }
    },

    priceData: () => price.getData(),
    klineData: () => klines.getData(),
    /** The kline chart through the incremental session: one candle
     * group patches per update when the step domain holds. */
    klineVnode() {
      const result = klineSession.tick();
      klineModes[result.mode]++;
      return result.vnode;
    },
    klineModes: () => ({ ...klineModes }),
    stats: () => ({ messages, drops }),
  };
}

/** A connection status, in the page's words. */
const STATUS = {
  live: 'site/charts/live/status-live',
  connecting: 'site/charts/live/status-connecting',
  reconnecting: 'site/charts/live/status-reconnecting',
  closed: 'site/charts/live/status-closed',
};

/**
 * The render nodes for a feed snapshot + connection status.
 * @param {any} feed - a `createBinanceFeed()` feed
 * @param {'live' | 'connecting' | 'reconnecting' | 'closed'} status
 * @param {string} [note] - the status card's line, in the page's words
 * @param {(id: any, params?: Record<string, unknown>) => string} [say] - the
 *   site's words (English by default)
 */
export function binanceNodes(feed, status, note, say = ENGLISH) {
  const { messages, drops } = feed.stats();
  const nodes = [
    cards([
      { title: say('site/charts/live/feed'), value: say(STATUS[status]), note: note ?? `${SYMBOLS.join(' + ')} · miniTicker + kline_1m` },
      { title: say('site/charts/live/messages'), value: String(messages), note: say('site/charts/live/dropped', { count: drops }) },
    ]),
  ];
  const priceData = feed.priceData();
  if (priceData.series.length > 0) {
    nodes.push(chart(null, compileChart(priceConfig(say), priceData, { theme: 'host' }).toVnode(),
      'Each point is one WebSocket message, parsed by createJsonxStreamReader in strict-JSON mode. '
      + `${SYMBOLS[0]} reads the left axis and ${SYMBOLS[1]} the right, each scaled to its own range so both moves show.`));
  }
  const klineData = feed.klineData();
  if (klineData.candles.length > 0) {
    const modes = feed.klineModes();
    nodes.push(chart(null, feed.klineVnode(),
      'Seeded from one REST klines call, updated live through the incremental session — '
      + `the open candle patches in place (${modes.incremental} incremental / ${modes.rebuilt} rebuilt frames so far).`));
  }
  return nodes;
}

/**
 * The opt-in invitation (nothing has connected yet).
 * @param {(id: any, params?: Record<string, unknown>) => string} [say] - the
 *   site's words (English by default)
 */
export function binanceInvitation(say = ENGLISH) {
  return [
    callout(say('site/charts/live/opt-in'),
      'This demo connects your browser to Binance (data-stream.binance.vision) and streams real ticker + kline messages through the strict-JSON streaming reader. Connecting sends your IP address to Binance; some regions block these endpoints — if so, the page stays fully usable.'),
    more(TOGGLE_ACTION, say('site/charts/live/go-live')),
  ];
}

//#region connection controller (browser-native WebSocket + fetch)

/** The /charts page owns the live slot; one socket exists at a time. */
const TOGGLE_ACTION = 'charts-live/toggle';
const sink = (dispatch, nodes) => dispatch('charts-live/set', nodes);

/** @type {{ws: any, feed: any, dispatch: any, words: () => any, raf: boolean, closed: boolean, retried: boolean}|null} */
let session = null;

const scheduleFrame = (cb) =>
  (typeof requestAnimationFrame === 'function' ? requestAnimationFrame(cb) : setTimeout(cb, 100));

/** Whether the live connection is open (test hook). */
export function binanceLiveActive() {
  return session !== null;
}

/** Paint the session's nodes; `noteId` names the status line in the site's words. */
function paint(status, noteId) {
  if (session === null) return;
  const say = session.words();
  sink(session.dispatch, binanceNodes(session.feed, status, noteId === undefined ? undefined : say(noteId), say));
}

function requestPaint() {
  if (session === null || session.raf) return;
  session.raf = true;
  scheduleFrame(() => {
    if (session === null) return;
    session.raf = false;
    paint('live');
  });
}

/**
 * Start/stop from a "Go live" button.
 * @param {(action: string, payload: any) => void} dispatch
 * @param {() => (id: any, params?: Record<string, unknown>) => string} [words] -
 *   the site's words in the reader's language, read at every paint (English by default)
 */
export function binanceToggle(dispatch, words = englishWords) {
  if (session !== null) {
    const { feed } = session;
    const say = session.words();
    stopBinance();
    sink(dispatch, [
      ...binanceNodes(feed, 'closed', say('site/charts/live/stopped'), say),
      ...binanceInvitation(say),
    ]);
    return;
  }
  startBinance(dispatch, words);
}

/**
 * Route hook for the /charts page: closes the socket when the page is
 * left. Never starts a connection — only the explicit toggle does.
 * The closed state is SUNK into the app (a stop alone would leave the
 * last painted nodes labeled `live` with no Go-live control on a
 * return visit).
 * @param {boolean} isActive
 */
export function binancePageSync(isActive) {
  if (session !== null && !isActive) {
    const { feed, dispatch } = session;
    const say = session.words();
    stopBinance();
    sink(dispatch, [
      ...binanceNodes(feed, 'closed', say('site/charts/live/left'), say),
      ...binanceInvitation(say),
    ]);
  }
}

export function stopBinance() {
  if (session === null) return;
  const s = session;
  session = null; // clear first: the close handler must not re-enter
  s.closed = true;
  try {
    s.ws?.close();
  }
  catch {
    // already closed
  }
}

function startBinance(dispatch, words) {
  const WS = globalThis.WebSocket;
  if (typeof WS !== 'function') {
    const say = words();
    sink(dispatch,
      [error({ message: say('site/charts/live/no-websocket') }, say('site/charts/live/cannot-connect'))]);
    return;
  }
  const feed = createBinanceFeed(words());
  session = { ws: null, feed, dispatch, words, raf: false, closed: false, retried: false };
  paint('connecting', 'site/charts/live/opening');

  // REST seed so the candlestick starts populated; response BODY text
  // goes through the same strict-JSON reader. Failure is non-fatal.
  if (typeof globalThis.fetch === 'function') {
    globalThis.fetch(`${REST_BASE}/api/v3/klines?symbol=${KLINE_SYMBOL}&interval=1m&limit=60`)
      .then((res) => (res.ok ? res.text() : Promise.reject(new Error(String(res.status)))))
      .then((text) => {
        if (session?.feed === feed) {
          feed.seedKlines(text);
          requestPaint();
        }
      })
      .catch(() => { /* geo-blocked or offline: the live feed still works */ });
  }

  connect(feed);
}

function connect(feed) {
  if (session === null || session.feed !== feed) return;
  const ws = new (globalThis.WebSocket)(`${WS_BASE}/stream?streams=${STREAMS.join('/')}`);
  session.ws = ws;
  ws.onopen = () => {
    if (session?.ws === ws) paint('live', 'site/charts/live/connected');
  };
  ws.onmessage = (event) => {
    if (session?.ws !== ws) return;
    feed.handleMessage(event.data);
    requestPaint();
  };
  ws.onerror = () => { /* the close handler reports */ };
  ws.onclose = () => {
    if (session === null || session.ws !== ws || session.closed) return;
    if (!session.retried) {
      session.retried = true;
      paint('reconnecting', 'site/charts/live/retrying');
      connect(feed);
      return;
    }
    const { dispatch } = session;
    const say = session.words();
    stopBinance();
    sink(dispatch, [
      ...binanceNodes(feed, 'closed', say('site/charts/live/lost'), say),
      callout(say('site/charts/live/feed-closed'), 'The Binance connection closed twice — it may be geo-blocked or offline from here. The rest of the page is unaffected; press Go live to try again.'),
      more(TOGGLE_ACTION, say('site/charts/live/go-live')),
    ]);
  };
}

//#endregion
